package com.agacostays.payment.client;
import com.agacostays.payment.dto.response.RestaurantOrderResponse; import com.agacostays.payment.exception.BusinessRuleException; import tools.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.math.BigDecimal;
@Component public class RestaurantServiceClient { private final RestClient client; public RestaurantServiceClient(RestClient.Builder b,@Value("${services.restaurant.base-url}")String url){client=b.baseUrl(url).build();} public RestaurantOrderResponse getOrder(String id){try{JsonNode n=client.get().uri("/api/restaurant/orders/{id}",id).retrieve().body(JsonNode.class);return new RestaurantOrderResponse(id,longV(n,"branchId"),longV(n,"customerId"),amount(n),text(n,"paymentStatus"),text(n,"orderStatus"));}catch(Exception e){throw new BusinessRuleException("Restaurant service unavailable or order not found");}} private Long longV(JsonNode n,String k){return n.path(k).isNumber()?n.get(k).longValue():null;} private BigDecimal amount(JsonNode n){for(String k:new String[]{"amount","orderAmount","totalAmount"})if(n.path(k).isNumber())return n.get(k).decimalValue();return BigDecimal.ZERO;} private String text(JsonNode n,String k){return n.path(k).isMissingNode()?null:n.path(k).asText();} }
